/**
 * Shape of the conformance fixtures generated by `gradlew generateTsFixtures`
 * from the Kotlin implementation. `cases.ts` and `expected/*.txt` are
 * generated; this file is hand-written and is the contract between the
 * generator and the test harness.
 */

export type CaseKind = "parse" | "loadError" | "parseError"

/**
 * How the parser under test is built:
 * - `text`: `loadGrammar(grammar, options)`
 * - `ast`: parse `grammar` with the yccc grammar, then `loadGrammarFromAst`
 *   (`astDepth: 2` repeats one more bootstrap level)
 * - `grammarParser`: the hand-written `GrammarParser`
 */
export type CaseMode = "text" | "ast" | "grammarParser"

export interface CaseLocale {
  language: string
  entries?: Record<string, string>
}

export interface CaseOptions {
  caseSensitive?: boolean
  splitWord?: boolean
  leftRecurDetection?: boolean
  useMemorizedParser?: boolean
  locale?: CaseLocale
}

export interface CaseSpec {
  name: string
  kind: CaseKind
  mode: CaseMode
  astDepth?: 1 | 2
  grammar?: string
  parseByName?: string
  input: string
  options?: CaseOptions
}
